@CrossOrigin
@RestController
@RequestMapping("/IncidentQuery")
public class IncidentQueryRestController extends BaseSpringRestController {
	
	public IncidentQueryRestController( IncidentService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Incident using a UUID
     * @param		UUID incidentId
     * @return		Incident
     */    
    @GetMapping("/load")
    public Incident load( @RequestParam(required=true) UUID incidentId ) {
    	Incident entity = null;

    	try {  
    		entity = service.getIncident( new IncidentFetchOneSummary( incidentId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Incident using Id " + incidentId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Incident business objects
     * @return		Set<Incident>
     */
    @GetMapping("/")
    public List<Incident> loadAll() {                
    	List<Incident> incidentList = null;
        
    	try {
            // load the Incident
            incidentList = service.getAllIncident();
            
            if ( incidentList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Incidents" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Incidents ", exc );
        	return null;
        }

        return incidentList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Incident incident = null;
    protected IncidentService service = null;
    private static final Logger LOGGER = Logger.getLogger(IncidentQueryRestController.class.getName());
    
}
